import{z as n,x as o,o as A,c as s,q as B,j as e,D as a,d as r,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"长上下文收束","description":"","frontmatter":{"title":"长上下文收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-map.md","filePath":"llm/lc-map.md","lastUpdated":1791413859000}'),m={name:"llm/lc-map.md"};function c(p,E,D,d,h,F){const l=o("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="长上下文收束" tabindex="-1">长上下文收束 <a class="header-anchor" href="#长上下文收束" aria-label="Permalink to &quot;长上下文收束&quot;">​</a></h1><div class="epigraph"><p>窗口是模型的能力，账本是系统的能力；系统工程让「支持 128K」第一次成为可以兑现的句子。</p><footer>—— 据本课程整理</footer></div><p><a href="/llm/lc-failure-catalog">上一课</a>把失败编成跨层清单，最后一格留给了机制回指。至此账已算清、池已调度、契约已立、门禁已设、失败已编目——本课程到此收束。收束做两件事：把十一课收进几条线，把本课程放回大图，留给后课一个干净的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要防的是把课程读成技巧堆砌：切块、缓存、外推表、门禁，单看都是工程技巧，合起来才是一套方法。散着记，换一个模型、换一个长度档位就全部重来；收进结构，重算的只有常数。所以收束的问题不是复述，是提炼：十一课里哪些是不随长度与模型改变的结构，哪些只是本次部署的常数。</p><p><span class="marginnote">术语翻译：「旋钮进门禁」是说每个可调参数（旋钮）都必须配一个盯着它的验收测试（门禁）。门禁就是上线前必须通过的自动化考题集：旋钮改动后考题不过，改动就出不了门——参数从此不能悄悄地坏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条线。资源线是「显存与调度」单元：<a href="/llm/lc-memory-account">显存账</a>把字节的账算全，立下「按积不按条」的纪律；<a href="/llm/lc-chunked-prefill">chunked prefill 深入</a>把峰值与带宽的兑换定价；<a href="/llm/lc-context-cache-tiers">缓存分层</a>把重算与恢复定价。契约线是「服务语义」单元：<a href="/llm/lc-retrieval-hybrid-serving">检索混合</a>、<a href="/llm/lc-extrapolation-serving">外推配置</a>、<a href="/llm/lc-longoutput-streaming">长输出流式</a>、<a href="/llm/lc-multidoc-workload">多文档共享</a>，四课各把一类系统行为变成对调用方可声明的分支与承诺。门槛线是「工程化」单元：<a href="/llm/lc-eval-serving">评测服务化</a>把旋钮钉进协议，<a href="/llm/lc-cost-case">成本案例</a>把杠杆排成顺序，<a href="/llm/lc-failure-catalog">失败清单</a>把故障编成排查法。三条线是同一句话的三种说法：长上下文不是「更长的窗口」，是把窗口的代价变成可会计、可调度、可约定的对象。</p>',8)),(A(),e(i,null,{default:a(()=>[t(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E6%98%BE%E5%AD%98%E8%B4%A6%EF%BC%9A%E5%9B%9B%E6%A0%8F%E4%B8%8E%E7%A7%AF%22%5D%20--%3E%20CUT%5B%22%E5%88%87%E5%9D%97%EF%BC%9A%E5%B3%B0%E5%80%BC%E6%8D%A2%E5%B8%A6%E5%AE%BD%E7%9A%84%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20CUT%20--%3E%20TIER%5B%22%E5%88%86%E5%B1%82%EF%BC%9A%E6%81%A2%E5%A4%8D%E6%8D%A2%E9%87%8D%E7%AE%97%E7%9A%84%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20TIER%20--%3E%20MIX%5B%22%E6%A3%80%E7%B4%A2%E6%B7%B7%E5%90%88%EF%BC%9A%E5%8F%8C%E5%B3%B0%E4%B8%8E%E7%BB%84%E8%A3%85%22%5D%0A%20%20MIX%20--%3E%20EXT%5B%22%E5%A4%96%E6%8E%A8%E5%A5%91%E7%BA%A6%EF%BC%9A%E9%85%8D%E7%BD%AE%E4%B8%8E%E8%B6%85%E7%AA%97%E5%88%86%E6%94%AF%22%5D%0A%20%20EXT%20--%3E%20STR%5B%22%E9%95%BF%E8%BE%93%E5%87%BA%EF%BC%9A%E5%88%86%E4%BD%8D%E6%95%B0%E4%B8%8E%E9%99%8D%E7%BA%A7%E5%8F%AF%E8%A7%81%22%5D%0A%20%20STR%20--%3E%20MDOC%5B%22%E5%A4%9A%E6%96%87%E6%A1%A3%EF%BC%9A%E5%85%B1%E4%BA%AB%E7%BB%93%E6%9E%84%E4%B8%8E%E5%A4%B1%E6%95%88%E5%8D%8A%E5%BE%84%22%5D%0A%20%20MDOC%20--%3E%20EVAL%5B%22%E8%AF%84%E6%B5%8B%E6%9C%8D%E5%8A%A1%E5%8C%96%EF%BC%9A%E6%97%8B%E9%92%AE%E8%BF%9B%E9%97%A8%E7%A6%81%22%5D%0A%20%20EVAL%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E6%A1%88%E4%BE%8B%EF%BC%9A%E6%95%B0%E9%87%8F%E7%BA%A7%E6%8E%92%E5%BA%8F%22%5D%0A%20%20COST%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%EF%BC%9A%E8%B7%A8%E5%B1%82%E6%8E%92%E6%9F%A5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>放回大图。往回接：KV 管理与压缩的深钻线把刀铸好——<a href="/llm/kv-quant-int8-int4">量化</a>、<a href="/llm/kv-eviction-heuristics">驱逐</a>、<a href="/llm/kv-offload">offload</a>各有专课；本课程回答刀往哪里用：进预算表、进降级链、进门禁。往回再接一层，主干把<a href="/llm/long-context-memory-curve">三条显存曲线</a>与<a href="/llm/serving-cost-model">服务成本模型</a>画全，本课程把曲线变成系统：曲线是物理，账本是决策。窗口继续增长时——多模态的长序列、代理轨迹的累积——课程里的常数全部重测：块长、恢复带宽、积的倍数；结构不变：四栏账、三条线、按积不按条、旋钮进门禁。这就是收束留下的接口：后课遇到「更长的东西」，先补账，再立契约，后设门禁。</p><p><span class="marginnote">一句自检：任何「长上下文方案」若说不清账记在哪几栏、契约有哪些分支、门禁测哪些任务族，它就还只是一个技巧——技巧在下一个长度档位就会失效，结构不会。</span></p><p>上面的链条回答「课程按什么顺序读」；换个问题——窗口继续涨、来了一个新需求时，三条线各自做什么、最后怎么合——是下面这张图的事。</p>',4)),(A(),e(i,null,{default:a(()=>[t(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E9%9C%80%E6%B1%82%EF%BC%9A%E6%9B%B4%E9%95%BF%E7%9A%84%E5%BA%8F%E5%88%97%20%2F%20%E6%96%B0%E6%A8%A1%E6%80%81%22%5D%20--%3E%20R%5B%22%E8%B5%84%E6%BA%90%E7%BA%BF%EF%BC%9A%E9%87%8D%E6%B5%8B%E5%B8%B8%E6%95%B0%E3%80%81%E8%A1%A5%E5%9B%9B%E6%A0%8F%E8%B4%A6%22%5D%0A%20%20NEW%20--%3E%20C%5B%22%E5%A5%91%E7%BA%A6%E7%BA%BF%EF%BC%9A%E7%AB%8B%E5%88%86%E6%94%AF%E4%B8%8E%E6%89%BF%E8%AF%BA%22%5D%0A%20%20NEW%20--%3E%20G%5B%22%E9%97%A8%E6%A7%9B%E7%BA%BF%EF%BC%9A%E6%97%8B%E9%92%AE%E8%BF%9B%E9%97%A8%E7%A6%81%22%5D%0A%20%20R%20--%3E%7C%22%E5%9D%97%E9%95%BF%E3%80%81%E6%81%A2%E5%A4%8D%E5%B8%A6%E5%AE%BD%E3%80%81%E7%A7%AF%E7%9A%84%E5%80%8D%E6%95%B0%22%7C%20D1%5B%22%E8%B4%A6%E5%8F%AF%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20C%20--%3E%7C%22%E8%B6%85%E7%AA%97%E5%88%86%E6%94%AF%E3%80%81%E9%99%8D%E7%BA%A7%E6%A0%87%E6%B3%A8%22%7C%20D2%5B%22%E8%A1%8C%E4%B8%BA%E5%8F%AF%E7%BA%A6%E5%AE%9A%22%5D%0A%20%20G%20--%3E%7C%22%E9%92%88%E6%B5%8B%E3%80%81%E4%BB%BB%E5%8A%A1%E6%97%8F%E9%AA%8C%E6%94%B6%22%7C%20D3%5B%22%E5%8F%91%E5%B8%83%E5%8F%AF%E5%AE%88%E4%BD%8F%22%5D%0A%20%20D1%20--%3E%20SHIP%5B%22%E4%B8%8A%E7%BA%BF%EF%BC%9A%E7%BB%93%E6%9E%84%E4%B8%8D%E5%8F%98%EF%BC%8C%E5%B8%B8%E6%95%B0%E5%B7%B2%E6%8D%A2%22%5D%0A%20%20D2%20--%3E%20SHIP%0A%20%20D3%20--%3E%20SHIP%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">常见误区：容易把三条线读成先后流程，以为算完账才立契约。实际上它们是同一个新需求的三份并行作业：账答「付得起吗」，契约答「做不到时怎么声明」，门禁答「凭什么信」——缺任何一份，方案都会在某个长度档位翻车。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p><span class="marginnote">直觉类比：「结构不变、常数重测」可以类比搬家装修：户型（四栏账、三分支、门禁）是承重墙，搬进新家不用砸；家具尺寸（块长、带宽、积的倍数）每次搬家都要重新量。把技巧误当结构的人，换个模型就等于把整套房子重新装修一遍。</span></p><p>本课程是服务侧的收束：训练侧的延窗续训（<a href="/llm/long-context-finetune">长上下文微调</a>）、内核侧的长序列核（<a href="/llm/ak-longsequence-kernels">长序列内核</a>）、检索栈的内部（<a href="/llm/rag-chunking">切分课</a>）各有其课，这里只做把三者接进服务的账与契约。课程案例的数字随模型与硬件过期；四栏、三分支、双口径这些结构不过期。深钻层在此收束一门课，不收束一个领域：长度还在涨，账本会一直写下去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条线收束：资源线算清代价，契约线声明行为，门槛线守住发布。</li><li>核心句式：长上下文工程是把窗口的代价变成可会计、可调度、可约定的对象。</li><li>往回接 KV 压缩线与主干曲线：刀在彼处铸成，账在此处使用。</li><li>常数随长度与硬件重测，结构（四栏账、三分支、双口径、门禁）跨档位复用。</li><li>遇到「更长的东西」：先补账，再立契约，后设门禁。</li><li>出处：本课程各课口径汇总——Pope et al., 2022；Kwon et al., SOSP 2023；Agrawal et al., OSDI 2024；Zheng et al., NeurIPS 2024；Peng et al., 2023；Liu, Zaharia 与 Abbeel, Ring Attention（2023）；其余见各课小节。</li></ul>',6))])}const u=n(m,[["render",c]]);export{f as __pageData,u as default};
